"use strict";
let made = null;
let kept = null;
exports.make = () => {
  if (made !== null) return made;
  made = {
    n: 1,
    inner: { n: 2 },
    opt: { n: 3 },
    either: { n: 4 },
    byName: { a: { n: 5 } },
    deep: { a: { b: { n: 6 } } },
    box: { value: { n: 7 } },
    mixed: { n: 8, extra: "x" },
    chain: { v: 1, next: { v: 2, next: { v: 3 } } },
    label: () => "made",
    bytes: new Uint8Array([1, 2, 3]),
    later: Promise.resolve(9),
  };
  made.job = Promise.resolve(made.inner);
  return made;
};
exports.later = () => Promise.resolve(exports.make());
exports.touch = () => {
  made.inner.n = 92;
  made.opt.n = 93;
  made.either.n = 94;
  made.byName.a.n = 95;
  made.deep.a.b.n = 96;
  made.box.value.n = 97;
  made.mixed.n = 98;
  made.chain.next.v = 99;
};
exports.same = (a, b) => a === b;
exports.innerOf = () => made.inner;
exports.describe = () => JSON.stringify([made.inner, made.byName, made.chain]);
exports.keep = (v) => (kept = v);
exports.bumpKept = () => {
  kept.inner.n += 10;
  kept.byName.b = { n: 50 };
};
